package dev.dymith.browser

/** Lightweight new-tab page. Kept self-contained: no framework, no remote runtime, no image hero. */
object StartPage {
    const val URL = "https://start.dymith.invalid/"

    val HTML: String = """
<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, interactive-widget=resizes-content">
<meta name="theme-color" content="#FFFFFF">
<title>Dymith</title>
<style>
:root{--bg:#fff;--ink:#000;--mute:#737373;--surf:#f5f5f5;--line:#e5e5e5;--acc:#000;--acc-ink:#fff;--sh:0 8px 24px rgba(0,0,0,.08);color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#000;--ink:#fff;--mute:#a3a3a3;--surf:#121212;--line:#2a2a2a;--acc:#fff;--acc-ink:#000;--sh:none;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#000;--ink:#fff;--mute:#a3a3a3;--surf:#121212;--line:#2a2a2a;--acc:#fff;--acc-ink:#000;--sh:none;color-scheme:dark}
:root[data-theme="light"]{--bg:#fff;--ink:#000;--mute:#737373;--surf:#f5f5f5;--line:#e5e5e5;--acc:#000;--acc-ink:#fff;--sh:0 8px 24px rgba(0,0,0,.08);color-scheme:light}
*,*::before,*::after{box-sizing:inherit}html,body{height:100%;height:100dvh}html{scroll-padding-top:env(safe-area-inset-top,0px)}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.4 ui-rounded,"SF Pro Rounded",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;-webkit-tap-highlight-color:transparent;overflow:hidden}button,input{font:inherit;color:inherit}button{cursor:pointer;border:0;background:none;padding:0}:focus-visible{outline:2px solid var(--acc);outline-offset:2px}.glyph{width:20px;height:20px;display:block;pointer-events:none}
.stage{height:100%;max-width:520px;margin:0 auto;display:flex;flex-direction:column;padding:24px 0 100px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none}.stage::-webkit-scrollbar{display:none}.top{padding:0 24px;margin-bottom:auto}.hello{margin:0;color:var(--mute);font-size:15px}.clock{margin:2px 0 0;font-size:clamp(68px,24vw,104px);font-weight:300;letter-spacing:-.045em;line-height:1;font-variant-numeric:tabular-nums}.date{margin:8px 0 0;color:var(--mute);font-size:15px;text-transform:capitalize}
.recent{display:flex;gap:8px;padding:28px 20px 16px;overflow-x:auto;scrollbar-width:none}.recent::-webkit-scrollbar{display:none}.recent:empty{display:none}.recent button{flex:none;display:flex;align-items:center;gap:8px;padding:9px 14px;border:1px solid var(--line);border-radius:999px;font-size:14px;max-width:70vw;background:var(--surf)}.recent span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.arc{display:grid;grid-template-columns:repeat(4,1fr);gap:22px 4px;padding:8px 12px 6px;margin-top:0}.recent:empty+.arc{margin-top:28px}.arc button{--dy:0px;display:flex;flex-direction:column;align-items:center;gap:7px;min-width:0;transform:translateY(var(--dy));animation:rise .42s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i)*35ms)}.arc button:nth-child(4n+1),.arc button:nth-child(4n){--dy:-18px}.ic{width:58px;height:58px;border-radius:19px;display:grid;place-items:center;font-weight:700;font-size:19px;background:var(--surf);color:var(--ink);overflow:hidden}.ic img{width:100%;height:100%;object-fit:contain;border-radius:19px;padding:12px}.arc small{font-size:12px;color:var(--mute);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.arc button:active .ic{transform:scale(.94)}@keyframes rise{from{opacity:0;transform:translateY(calc(var(--dy) + 22px))}}
.scrim{position:fixed;inset:0;background:var(--bg);opacity:0;pointer-events:none;transition:opacity .12s linear;z-index:5}body.open .scrim{opacity:.86;pointer-events:auto}
.dock{position:fixed;left:0;right:0;bottom:0;z-index:10;padding:0 12px calc(12px + env(safe-area-inset-bottom,0px));pointer-events:none}.dock>*{max-width:520px;margin-inline:auto;pointer-events:auto}.panel{display:flex;flex-direction:column;margin-bottom:8px;background:var(--surf);border:1px solid var(--line);border-radius:24px;box-shadow:var(--sh);max-height:min(60dvh,440px);overflow-y:auto;transform-origin:bottom;animation:pop .12s ease-out}.panel[hidden]{display:none}@keyframes pop{from{opacity:0;transform:translateY(6px)}}.sug{list-style:none;margin:0;padding:6px;display:flex;flex-direction:column-reverse}.sug:empty{display:none}.sug li:first-child .row{font-weight:600}.row{display:flex;align-items:center;gap:12px;width:100%;min-height:48px;padding:0 12px;border-radius:16px;text-align:left}.row:active{background:var(--bg)}.row canvas{flex:none;color:var(--mute)}.row span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.row small{color:var(--mute);font-size:13px}.chips{display:flex;gap:8px;padding:10px;overflow-x:auto;scrollbar-width:none}.chips::-webkit-scrollbar{display:none}.sug:not(:empty)+.chips{border-top:1px solid var(--line)}.chip{flex:none;padding:8px 14px;border:1px solid var(--line);border-radius:999px;font-size:14px;background:var(--bg)}.chip[aria-checked="true"]{background:var(--acc);border-color:var(--acc);color:var(--acc-ink);font-weight:600}.chip.ghost{color:var(--mute);border-style:dashed}
.bar{display:flex;align-items:center;gap:8px;height:58px;padding:6px;background:var(--surf);border:1px solid var(--line);border-radius:29px;box-shadow:var(--sh)}.eng{flex:none;width:44px;height:44px;border-radius:50%;background:var(--bg);font-weight:700;color:var(--ink)}#q{flex:1;min-width:0;height:44px;border:0;background:none;font-size:16px;outline:0;color:var(--ink)}#q::placeholder{color:var(--mute)}.bar:focus-within{border-color:var(--acc)}.go{flex:none;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:var(--bg);color:var(--mute);transition:background .1s linear,color .1s linear}.go.on{background:var(--acc);color:var(--acc-ink)}
@media(max-height:620px){.stage{padding-top:14px}.clock{font-size:clamp(56px,18vw,76px)}.recent{padding-top:16px}.arc{gap:12px 4px}.ic{width:50px;height:50px;border-radius:16px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style>
</head>
<body>
<main class="stage" id="stage"><header class="top"><p class="hello" id="hello"></p><h1 class="clock" id="clock">00:00</h1><p class="date" id="date"></p></header><section class="recent" id="recent" aria-label="Tìm gần đây"></section><section class="arc" id="arc" aria-label="Lối tắt"></section></main>
<div class="scrim" id="scrim"></div><div class="dock" id="dock"><div class="panel" id="panel" hidden><ul class="sug" id="sug"></ul><div class="chips" id="chips" role="radiogroup" aria-label="Công cụ tìm kiếm"></div></div><div class="bar"><button class="eng" id="engBtn" aria-label="Đổi công cụ tìm kiếm">G</button><input id="q" type="text" placeholder="Tìm kiếm hoặc nhập địa chỉ" enterkeyhint="go" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" aria-label="Tìm kiếm hoặc nhập địa chỉ"><button class="go" id="goBtn" aria-label="Đi"></button></div></div>
<script>
(function(){'use strict';
var $=function(s){return document.getElementById(s)};
var SITES=[['YouTube','youtube.com','https://www.google.com/s2/favicons?domain=youtube.com&sz=128'],['Facebook','facebook.com','https://www.google.com/s2/favicons?domain=facebook.com&sz=128'],['Zalo','chat.zalo.me','https://www.google.com/s2/favicons?domain=zalo.me&sz=128'],['Shopee','shopee.vn','https://www.google.com/s2/favicons?domain=shopee.vn&sz=128'],['VnExpress','vnexpress.net','https://www.google.com/s2/favicons?domain=vnexpress.net&sz=128'],['Gmail','mail.google.com','https://www.google.com/s2/favicons?domain=mail.google.com&sz=128'],['GitHub','github.com','https://www.google.com/s2/favicons?domain=github.com&sz=128'],['Wikipedia','vi.wikipedia.org','https://www.google.com/s2/favicons?domain=wikipedia.org&sz=128']];
var ENG=[['Google','https://www.google.com/search?q='],['DuckDuckGo','https://duckduckgo.com/?q='],['Bing','https://www.bing.com/search?q='],['Cốc Cốc','https://coccoc.com/search?query=']];
var TN={auto:'Tự động',light:'Sáng',dark:'Tối'};
var iconCanvas=function(name){return '<canvas class="glyph" data-icon="'+name+'" width="48" height="48" aria-hidden="true"></canvas>'};
var IC={go:iconCanvas('go'),search:iconCanvas('search'),clock:iconCanvas('clock'),globe:iconCanvas('globe')};
function drawGlyph(canvas){var dpr=Math.min(window.devicePixelRatio||1,2),ctx=canvas.getContext('2d');if(!ctx)return;canvas.width=24*dpr;canvas.height=24*dpr;ctx.scale(dpr,dpr);ctx.strokeStyle=getComputedStyle(canvas).color||'#000';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=2.1;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();switch(canvas.dataset.icon){case'go':ctx.moveTo(5,12);ctx.lineTo(19,12);ctx.moveTo(13,6);ctx.lineTo(19,12);ctx.lineTo(13,18);break;case'search':ctx.arc(10.5,10.5,7,0,Math.PI*2);ctx.moveTo(16,16);ctx.lineTo(21,21);break;case'clock':ctx.arc(12,12,9,0,Math.PI*2);ctx.moveTo(12,7);ctx.lineTo(12,12);ctx.lineTo(15.5,14);break;case'globe':ctx.arc(12,12,9,0,Math.PI*2);ctx.moveTo(3,12);ctx.lineTo(21,12);ctx.moveTo(12,3);ctx.ellipse(12,12,4,9,0,0,Math.PI*2);break;}ctx.stroke()}
function drawGlyphs(root){root.querySelectorAll('canvas.glyph').forEach(drawGlyph)}
var ls={get:function(k,d){try{var v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}},set:function(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};
var ei=ls.get('eng',0);if(!ENG[ei])ei=0;var hist=ls.get('hist',[]);if(!Array.isArray(hist))hist=[];var theme=ls.get('theme','auto');if(!TN[theme])theme='auto';
var q=$('q'),panel=$('panel'),sug=$('sug'),chips=$('chips'),recent=$('recent'),goBtn=$('goBtn'),engBtn=$('engBtn');
var esc=function(s){return String(s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})};
function isUrl(s){return !/\s/.test(s)&&(/^https?:\/\/\S+$/i.test(s)||/^localhost(:\d+)?(\/.*)?$/i.test(s)||/^[\w-]+(\.[\w-]+)+(:\d+)?(\/.*)?$/.test(s))}
function openUrl(u){if(window.Dymith&&typeof window.Dymith.postMessage==='function'){window.Dymith.postMessage(JSON.stringify({action:'navigate',url:u}))}else{window.location.href=u}}
function go(raw){var s=(raw||'').trim();if(!s)return;var u;if(isUrl(s)){u=/^https?:/i.test(s)?s:'https://'+s}else{u=ENG[ei][1]+encodeURIComponent(s);hist=[s].concat(hist.filter(function(h){return h.toLowerCase()!==s.toLowerCase()})).slice(0,8);ls.set('hist',hist)}q.value='';q.blur();setOpen(false);renderAll();openUrl(u)}
function row(kind,text,attr,sub){return '<li><button class="row" '+attr+'>'+IC[kind]+'<span>'+esc(text)+'</span>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</button></li>'}
function renderPanel(){var s=q.value.trim(),l=s.toLowerCase(),r=[];if(s){r.push(isUrl(s)?row('globe','Mở '+s,'data-q="'+esc(s)+'"'):row('search','Tìm “'+s+'” trên '+ENG[ei][0],'data-q="'+esc(s)+'"'));SITES.filter(function(x){return x[0].toLowerCase().indexOf(l)>-1||x[1].indexOf(l)>-1}).slice(0,3).forEach(function(x){r.push(row('globe',x[0],'data-url="https://'+x[1]+'"',x[1]))});hist.filter(function(h){var k=h.toLowerCase();return k.indexOf(l)>-1&&k!==l}).slice(0,3).forEach(function(h){r.push(row('clock',h,'data-q="'+esc(h)+'"'))})}else{hist.slice(0,5).forEach(function(h){r.push(row('clock',h,'data-q="'+esc(h)+'"'))})}sug.innerHTML=r.join('');chips.innerHTML=ENG.map(function(e,i){return '<button class="chip" role="radio" aria-checked="'+(i===ei)+'" data-eng="'+i+'">'+e[0]+'</button>'}).join('')+'<button class="chip ghost" data-act="theme">Giao diện: '+TN[theme]+'</button>'+(hist.length?'<button class="chip ghost" data-act="clear">Xóa lịch sử</button>':'');drawGlyphs(sug)}
function renderStage(){$('arc').innerHTML=SITES.map(function(x,i){return '<button type="button" data-url="https://'+x[1]+'" style="--i:'+i+'"><span class="ic"><img src="'+x[2]+'" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.remove();this.parentNode.textContent=\''+x[0].charAt(0)+'\'"></span><small>'+x[0]+'</small></button>'}).join('');recent.innerHTML=hist.slice(0,4).map(function(h){return '<button type="button" data-q="'+esc(h)+'">'+IC.clock+'<span>'+esc(h)+'</span></button>'}).join('');drawGlyphs(recent)}
function syncBar(){engBtn.textContent=ENG[ei][0].charAt(0);goBtn.innerHTML=IC.go;goBtn.classList.toggle('on',!!q.value.trim());drawGlyphs(goBtn)}
function renderAll(){renderStage();renderPanel();syncBar()}
function applyTheme(){var r=document.documentElement;if(theme==='auto')r.removeAttribute('data-theme');else r.setAttribute('data-theme',theme)}
function setOpen(o){document.body.classList.toggle('open',o);panel.hidden=!o;if(o)renderPanel()}
q.addEventListener('focus',function(){setOpen(true)});q.addEventListener('blur',function(){window.setTimeout(function(){if(!panel.contains(document.activeElement))setOpen(false)},120)});q.addEventListener('input',function(){renderPanel();syncBar()});q.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();go(q.value)}else if(e.key==='Escape'){q.blur()}});$('scrim').addEventListener('click',function(){q.blur();setOpen(false)});
$('dock').addEventListener('mousedown',function(e){if(e.target!==q)e.preventDefault()});goBtn.addEventListener('click',function(){if(q.value.trim())go(q.value);else q.focus()});engBtn.addEventListener('click',function(){ei=(ei+1)%ENG.length;ls.set('eng',ei);if(document.activeElement!==q)q.focus();renderPanel();syncBar()});
function pick(e){var b=e.target.closest('button');if(!b)return;var d=b.dataset;if(d.url)openUrl(d.url);else if(d.q)go(d.q);else if(d.eng!==undefined){ei=+d.eng;ls.set('eng',ei);renderPanel();syncBar()}else if(d.act==='theme'){theme=theme==='auto'?'light':theme==='light'?'dark':'auto';ls.set('theme',theme);applyTheme();renderPanel()}else if(d.act==='clear'){hist=[];ls.set('hist',hist);renderAll()}}
panel.addEventListener('click',pick);$('arc').addEventListener('click',pick);recent.addEventListener('click',pick);
var last='',clockTimer=0;function tick(){var d=new Date(),h=d.getHours(),t=('0'+h).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);if(t!==last){last=t;$('clock').textContent=t;$('hello').textContent=h<11?'Chào buổi sáng':h<14?'Chào buổi trưa':h<18?'Chào buổi chiều':'Chào buổi tối';$('date').textContent=d.toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}clockTimer=window.setTimeout(tick,Math.max(1000,60000-d.getSeconds()*1000-d.getMilliseconds()))}
function startClock(){window.clearTimeout(clockTimer);tick()}document.addEventListener('visibilitychange',function(){if(document.hidden)window.clearTimeout(clockTimer);else startClock()});
applyTheme();renderAll();startClock();
})();
</script>
</body></html>
""".trimIndent()
}
